// Match each report to the same document scope used by the desktop workspace.
export function reportDocuments(
  scope: string,
  withdrawn = false,
  topicId?: string,
) {
  return articles.filter(
    (a) =>
      (scope === "全部领域" || a.category === scope) &&
      (!topicId || a.topicId === topicId) &&
      (!withdrawn || a.id !== controlledDocument),
  );
}

