// Apply one event transition atomically; client, phase and evidence guards also cover stale tabs.
export function advanceCollaboration(
  state: MobileState,
  action: CollaborationAction,
  actor: CollaborationActor,
  input: { note?: string; checked?: boolean; assignment?: CaseAssignment },
  time: string,
  eventId: string,
  topicId = focusTopicId,
): MobileState {
  const topic = topics.find((t) => t.id === topicId);
  const risk = initialRisks.find((r) => r.topic === topicId);
  if (
    !topic ||
    !risk ||
    (input.assignment && !validAssignment(input.assignment))
  )
    return state;
  const c = caseWorkflow(state, topicId);
  const phase = c.phase;
  const reportId = caseReportId(topicId);
  const report = state.reports.find((r) => r.id === reportId);
  const note = input.note?.trim() || "";
  let next = state;
  let nextPhase: CollaborationPhase = phase;
  let title = "";
  const web = actor === "网页端";
  if (action === "assign" && web && phase === "identified") {
    next = { ...state, statuses: { ...state.statuses, [risk.id]: "复核中" } };
    nextPhase = "assigned";
    title = "核验任务已派发";
  } else if (
    action === "review" &&
    !web &&
    phase === "assigned" &&
    note.length >= 5
  ) {
    next = submitReview(state, risk.id, "通过复核", note, time);
    nextPhase = "reviewed";
    title = "核验意见已提交";
  } else if (
    action === "return" &&
    !web &&
    phase === "assigned" &&
    note.length >= 5
  ) {
    next = { ...state, statuses: { ...state.statuses, [risk.id]: "待确认" } };
    nextPhase = "identified";
    title = "核验退回，待补充材料";
  } else if (
    action === "draft" &&
    web &&
    phase === "reviewed" &&
    note.length >= 10
  ) {
    const draft: MobileReport = {
      id: reportId,
      title: `${topic.title}专题研判`,
      topicId,
      type: "专题报告",
      date: new Date().toLocaleDateString("sv-SE"),
      status: "待审核",
      scope: topic.category,
      coverage: "本事件关联原文",
      revision: (report?.revision || 0) + 1,
      evidenceIds: reportDocuments(
        topic.category,
        state.withdrawn,
        topicId,
      ).map((a) => a.id),
      stale: false,
      analysis: note,
    };
    next = {
      ...state,
      reports: [draft, ...state.reports.filter((r) => r.id !== reportId)],
    };
    nextPhase = "drafted";
    title = `研判报告 v${draft.revision} 已送审`;
  } else if (
    action === "approve" &&
    !web &&
    ["drafted", "rebuilt"].includes(phase) &&
    input.checked
  ) {
    if (!report || report.stale || report.status !== "待审核") return state;
    next = approveReport(state, reportId, true);
    nextPhase = "published";
    title = `研判报告 v${report.revision} 已审核发布`;
  } else if (
    action === "reject" &&
    !web &&
    ["drafted", "rebuilt"].includes(phase) &&
    note.length >= 5
  ) {
    if (!report || report.stale || report.status !== "待审核") return state;
    next = {
      ...state,
      reports: state.reports.map((r) =>
        r.id === reportId ? { ...r, status: "草稿" } : r,
      ),
    };
    nextPhase = phase === "rebuilt" ? "changed" : "reviewed";
    title = "报告已退回修改";
  } else if (
    action === "close" &&
    web &&
    phase === "published" &&
    input.checked &&
    note.length >= 5
  ) {
    if (!report || report.stale || report.status !== "已发布") return state;
    next = { ...state, statuses: { ...state.statuses, [risk.id]: "已归档" } };
    nextPhase = "completed";
    title = "事件已办结归档";
  } else if (
    action === "withdraw" &&
    web &&
    topicId === focusTopicId &&
    !state.withdrawn
  ) {
    next = withdrawSource(state);
    nextPhase = next.collaboration.phase;
    title = "来源撤回已登记";
  } else if (
    action === "rebuild" &&
    web &&
    phase === "changed" &&
    note.length >= 10 &&
    state.withdrawn &&
    report
  ) {
    next = rebuildReport(state, reportId);
    next = {
      ...next,
      reports: next.reports.map((r) =>
        r.id === reportId ? { ...r, analysis: note } : r,
      ),
    };
    nextPhase = "rebuilt";
    title = "报告已更新，等待重新审核";
  } else return state;
  const detail =
    note ||
    (action === "assign" && input.assignment
      ? `${input.assignment.department} · ${input.assignment.assignee}；办理期限 ${input.assignment.dueAt.replace("T", " ")}。${input.assignment.instruction}`
      : action === "withdraw"
        ? "撤回原文已停止读取，关联报告标记待更新；历史判断及办理记录保留。"
        : title);
  const workflow: CollaborationState = {
    ...c,
    phase: nextPhase,
    ...(action === "assign" && input.assignment
      ? { assignment: input.assignment }
      : {}),
    analysis: ["draft", "rebuild"].includes(action) ? note : c.analysis,
    feedback: ["review", "return", "reject"].includes(action)
      ? note
      : c.feedback,
    events: [...c.events, { id: eventId, actor, title, detail, time }],
  };
  return {
    ...next,
    ...(topicId === focusTopicId
      ? { collaboration: workflow }
      : { caseWorkflows: { ...next.caseWorkflows, [topicId]: workflow } }),
    activity: [
      { id: eventId, title, detail, route: `collaboration/${topicId}`, time },
      ...next.activity,
    ],
  };
}

// Rebuild against available evidence; human approval is required again for the new version.
export function rebuildReport(state: MobileState, id: string): MobileState {
  return {
    ...state,
    reports: state.reports.map((r) =>
      r.id === id
        ? {
            ...r,
            revision: r.revision + 1,
            status: "待审核",
            stale: false,
            evidenceIds: reportDocuments(
              r.scope,
              state.withdrawn,
              r.topicId,
            ).map((a) => a.id),
          }
        : r,
    ),
  };
}

// Guard the same publication conditions regardless of which screen invokes approval.
export function approveReport(
  state: MobileState,
  id: string,
  checked: boolean,
): MobileState {
  return {
    ...state,
    reports: state.reports.map((r) =>
      r.id === id && checked && !r.stale && r.status === "待审核"
        ? { ...r, status: "已发布" }
        : r,
    ),
  };
}

// Keep the risk status and the human decision log in a single state transition.
export function submitReview(
  state: MobileState,
  riskId: string,
  result: ReviewResult,
  note: string,
  time: string,
): MobileState {
  if (
    note.trim().length < 5 ||
    !initialRisks.some((r) => r.id === riskId) ||
    !["通过复核", "补充材料", "排除线索"].includes(result)
  )
    return state;
  return {
    ...state,
    statuses: {
      ...state.statuses,
      [riskId]:
        result === "通过复核"
          ? "已确认"
          : result === "排除线索"
            ? "已归档"
            : "复核中",
    },
    reviews: [{ riskId, result, note: note.trim(), time }, ...state.reviews],
  };
}

// Both report readers summarize the exact evidence membership of the selected revision.
export function reportTopicMetrics(report: MobileReport) {
  return topics
    .filter((topic) =>
      report.evidenceIds.some((id) =>
        articles.some((a) => a.id === id && a.topicId === topic.id),
      ),
    )
    .map((topic) => {
      const records = articles.filter(
        (a) => report.evidenceIds.includes(a.id) && a.topicId === topic.id,
      );
      const negativeCount = records.filter(
        (a) => a.sentiment === "负面",
      ).length;
      return {
        ...topic,
        count: records.length,
        negativeCount,
        negative: Number(((negativeCount / records.length) * 100).toFixed(1)),
      };
    });
}

// Keep desktop and mobile downloads identical, with no original text from withdrawn evidence.
export function reportMarkdown(report: MobileReport, withdrawn = false) {
  if (report.stale || report.status !== "已发布") return "";
  const docs = articles.filter(
    (a) =>
      report.evidenceIds.includes(a.id) &&
      (!withdrawn || a.id !== controlledDocument),
  );
  return `# ${report.title}\n\n报告编号：${report.id} · 版本 v${report.revision}\n观察快照：${snapshotTime}\n监管领域：${report.scope}\n覆盖口径：当前样本快照\n\n## 观察摘要\n本版本引用 ${docs.length} 条原文，其中 ${docs.filter((a) => a.sentiment === "负面").length} 条负面表达。\n\n## 重点话题与证据统计\n${reportTopicMetrics(
    report,
  )
    .map(
      (t) =>
        `- ${t.title}：${t.count} 条原文；负面 ${t.negativeCount} 条，占比 ${t.negative}%。${t.summary}`,
    )
    .join(
      "\n",
    )}\n\n## 研判建议\n${report.analysis || "核对经营主体、订单与原始材料，区分公众反馈、经营者自述和核查结果；持续跟踪整改与后续反馈。"}\n\n## 证据索引\n${docs.map((a) => `- [${a.evidence}] ${a.title}（${a.source} · ${a.observedAt}）`).join("\n")}\n\n数据说明：内置虚构样本；负面表达与风险等级不等于违法或事故认定。当前记录可逐条复算，历史增幅使用上一窗口汇总对照。`;
}
